// A Paper plugin: Kotlin, shadow jar and a paper-plugin.yml generated by plugin-yml
plugins {
    id("kiln.kotlin")
    id("kiln.shadow")
    id("de.eldoria.plugin-yml.paper")
}

val libs = the<VersionCatalogsExtension>().named("libs")

paper {
    version = project.version.toString()
    apiVersion = libs.findVersion("minecraft").get().requiredVersion
}
